-- Reset ID sequences so future inserts continue after the seed IDs
SELECT setval(pg_get_serial_sequence('departments', 'department_id'), (SELECT MAX(department_id) FROM departments));
SELECT setval(pg_get_serial_sequence('job_titles', 'job_title_id'), (SELECT MAX(job_title_id) FROM job_titles));
SELECT setval(pg_get_serial_sequence('attendance_status', 'status_id'), (SELECT MAX(status_id) FROM attendance_status));
SELECT setval(pg_get_serial_sequence('time_periods', 'period_id'), (SELECT MAX(period_id) FROM time_periods));
SELECT setval(pg_get_serial_sequence('performance_ratings', 'rating_id'), (SELECT MAX(rating_id) FROM performance_ratings));
SELECT setval(pg_get_serial_sequence('employees', 'employee_id'), (SELECT MAX(employee_id) FROM employees));
SELECT setval(pg_get_serial_sequence('attendance', 'attendance_id'), (SELECT MAX(attendance_id) FROM attendance));
SELECT setval(pg_get_serial_sequence('performance_reviews', 'review_id'), (SELECT MAX(review_id) FROM performance_reviews));
SELECT setval(pg_get_serial_sequence('productivity', 'productivity_id'), (SELECT MAX(productivity_id) FROM productivity));


-- Quick check: row counts
SELECT 'departments' AS table_name, COUNT(*) AS row_count FROM departments
